import type { TaskView, HarnessContext, Solution } from './contract.js';

export interface Failure {
  readonly kind: 'no-code-block' | 'empty-file' | 'model-error' | 'budget-exceeded';
  readonly detail: string;
}

/** One repair call, only when the draft came back empty. */
export async function attemptRepair(
  task: TaskView, ctx: HarnessContext, failure: Failure, _previousReply: string,
): Promise<Solution | null> {
  if (failure.kind !== 'empty-file') return null;
  const reply = await ctx.model.complete({
    label: 'repair#1',
    messages: [{ role: 'user', content: `Your last reply had no code. Write ${task.entryFile} now.` }],
    maxTokens: 2048,
  });
  return { files: [{ path: task.entryFile, contents: reply.text }], notes: reply.outputTokens };
}
